#[test]
fn test_local_context_len_and_empty() {
    // Kill mutants: LocalContext::len can return 0/1, is_empty can return true/false
    let mut ctx = LocalContext::new();

    // Initially empty
    assert!(ctx.is_empty());
    assert_eq!(ctx.len(), 0);

    // After one push
    let id1 = ctx.push(Name::anon(), Expr::prop(), BinderInfo::Default);
    assert!(!ctx.is_empty());
    assert_eq!(ctx.len(), 1);

    // After two pushes
    let id2 = ctx.push(Name::anon(), Expr::type_(), BinderInfo::Default);
    assert!(!ctx.is_empty());
    assert_eq!(ctx.len(), 2);

    // Verify we can retrieve both
    let decl1 = ctx.get(id1).expect("first pushed declaration should exist");
    assert_eq!(decl1.id, id1);
    assert_eq!(decl1.type_, Expr::prop());
    assert_eq!(decl1.value, None);
    let decl2 = ctx
        .get(id2)
        .expect("second pushed declaration should exist");
    assert_eq!(decl2.id, id2);
    assert_eq!(decl2.type_, Expr::type_());
    assert_eq!(decl2.value, None);

    // After one pop
    let popped = ctx
        .pop()
        .expect("first pop should return the most recent declaration");
    assert_eq!(popped.id, id2);
    assert_eq!(popped.type_, Expr::type_());
    assert_eq!(popped.value, None);
    assert_eq!(ctx.get(id2).map(|decl| decl.id), None);
    assert_eq!(ctx.len(), 1);
    assert!(!ctx.is_empty());

    // After second pop
    let popped = ctx
        .pop()
        .expect("second pop should return the remaining declaration");
    assert_eq!(popped.id, id1);
    assert_eq!(popped.type_, Expr::prop());
    assert_eq!(popped.value, None);
    assert_eq!(ctx.get(id1).map(|decl| decl.id), None);
    assert_eq!(ctx.len(), 0);
    assert!(ctx.is_empty());

    // Pop from empty returns None
    assert_eq!(ctx.pop().map(|decl| decl.id), None);
}

#[test]
fn test_local_context_let_binding() {
    // Kill mutants: push_let += with *=
    let mut ctx = LocalContext::new();

    let id1 = ctx.push_let(Name::anon(), Expr::prop(), Expr::prop());
    let id2 = ctx.push_let(Name::anon(), Expr::type_(), Expr::type_());

    // IDs must be distinct (tests += 1 vs *= 1)
    assert_ne!(id1, id2);

    // Both must be retrievable
    let decl1 = ctx.get(id1).unwrap();
    let decl2 = ctx.get(id2).unwrap();
    assert_eq!(decl1.type_, Expr::prop());
    assert_eq!(decl1.value, Some(Expr::prop()));
    assert_eq!(decl2.type_, Expr::type_());
    assert_eq!(decl2.value, Some(Expr::type_()));
}

