// --- abstract_fvar_in_expr BVar shift tests (#1309) ---

#[test]
fn test_abstract_fvar_shifts_existing_bvars() {
    // Directly test that pre-existing BVar(idx) where idx >= depth gets shifted
    // to BVar(idx + 1). This was the core bug in #1309: abstract_fvar_in_expr
    // returned BVars unchanged, risking index collision.
    let fvar_id = FVarId(42);

    // Expression: App(BVar(3), FVar(42))
    // At depth=2: BVar(3) >= 2, so it should become BVar(4)
    //             FVar(42) matches, so it should become BVar(2)
    let expr = Expr::app(Expr::bvar(3), Expr::fvar(fvar_id));
    let abstracted = abstract_fvar_in_expr(expr, fvar_id, 2);

    match &abstracted.kind {
        ExprKind::App(f, a) => {
            assert_eq!(
                f.as_ref().kind,
                ExprKind::BVar(4),
                "BVar(3) at depth=2 must shift to BVar(4)"
            );
            assert_eq!(
                a.as_ref().kind,
                ExprKind::BVar(2),
                "FVar(42) at depth=2 must become BVar(2)"
            );
        }
        _ => panic!("Expected App expression"),
    }
}

#[test]
fn test_abstract_fvar_preserves_bvars_below_depth() {
    // BVar(idx) where idx < depth should NOT be shifted
    let fvar_id = FVarId(42);

    // Expression: App(BVar(1), BVar(5))
    // At depth=3: BVar(1) < 3 → stays BVar(1)
    //             BVar(5) >= 3 → becomes BVar(6)
    let expr = Expr::app(Expr::bvar(1), Expr::bvar(5));
    let abstracted = abstract_fvar_in_expr(expr, fvar_id, 3);

    match &abstracted.kind {
        ExprKind::App(f, a) => {
            assert_eq!(
                f.as_ref().kind,
                ExprKind::BVar(1),
                "BVar(1) at depth=3 must stay BVar(1) (below depth)"
            );
            assert_eq!(
                a.as_ref().kind,
                ExprKind::BVar(6),
                "BVar(5) at depth=3 must shift to BVar(6)"
            );
        }
        _ => panic!("Expected App expression"),
    }
}

#[test]
fn test_convert_fvar_cert_shifts_existing_bvars() {
    // Directly test that ProofCert::BVar { idx } where idx >= depth gets shifted
    // to idx + 1, matching the fix in abstract_fvar_in_expr.
    let fvar_id = FVarId(42);

    // ProofCert with a BVar at idx=5 and depth=3
    // idx >= depth (5 >= 3), so should become idx=6
    let cert = ProofCert::BVar {
        idx: 5,
        expected_type: Box::new(Expr::prop()),
    };
    let converted = convert_fvar_cert_to_bvar(cert, fvar_id, 3);

    match converted {
        ProofCert::BVar { idx, .. } => {
            assert_eq!(idx, 6, "ProofCert::BVar(5) at depth=3 must shift to 6");
        }
        other => panic!("Expected BVar cert, got {other:?}"),
    }
}

